<?php require_once __DIR__.'/../app/layout.php';header_html('Notices');$rows=$pdo->query("SELECT * FROM notices WHERE status='active' AND audience IN ('public','both') AND publish_date<=CURDATE() AND (expiry_date IS NULL OR expiry_date>=CURDATE()) ORDER BY publish_date DESC")->fetchAll();?><h1>Notices</h1><?php foreach($rows as $n):?><article class="card"><h2><?=e($n['title'])?></h2><p><?=nl2br(e($n['description']))?></p></article><?php endforeach; footer_html();
